/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeMCRCustCategoryHierarchyName extends UPSPricingAttributeMCRCustCategoryHierarchy implements UPSIPricingAttribute
{
}

