public str getName()
{
    return fieldPName(MCRCustCategoryHierarchy, Name);
}

public Set getAllowedValues()
{
    var                      ret = new Set(Types::String);
    MCRCustCategoryHierarchy mCRCustCategoryHierarchy;

    while select mCRCustCategoryHierarchy
        group by Name
    {
        if (! ret.in(mCRCustCategoryHierarchy.Name))
        {
            ret.add(mCRCustCategoryHierarchy.Name);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(MCRCustCategoryHierarchy, Name));
    qbr.value(queryValue(_value));
}
